//! Per-instruction conformance tests for the translator.
//!
//! The build script translates the synthetic programs in [`programs`] into
//! Rust; the tests run each one many times from random register and memory
//! states, on both the translated code and the reference CPU
//! (`n64rusty-refcpu`), and require identical registers, HI/LO and memory.
//! No game code or data is involved.

pub mod asm;
pub mod programs;

/// Translated programs, generated by the build script.
#[allow(clippy::all, clippy::pedantic, unused)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/generated.rs"));
}
